      "resource": "azurerm_mssql_server.changeme_simple_mssql_server",
      "severity": "MEDIUM",
      "explanation": "Auditing is not enabled for the SQL server, which can lead to a lack of visibility into potential security issues."
    },
    {
      "check_id": "CKV_AZURE_113",
      "title": "Ensure that SQL server disables public network access",
      "resource": "azurerm_mssql_server.changeme_simple_mssql_server",
      "severity": "MEDIUM",
      "explanation": "The SQL server has public network access enabled by default, which can expose it to unauthorized access."
    },
    {
      "check_id": "CKV2_AZURE_2",
      "title": "Ensure that Vulnerability Assessment (VA) is enabled on a SQL server by setting a Storage Account",
      "resource": "azurerm_mssql_server.changeme_simple_mssql_server",
      "severity": "MEDIUM",
      "explanation": "Vulnerability Assessment is not enabled on the SQL server, which can leave it vulnerable to unidentified security risks."
    }
  ],
  "patched_code": "resource \"azurerm_mssql_server\" \"changeme_simple_mssql_server\" {\n  name                = \"changeme-simple-mssql-database-name\"\n  resource_group_name = azurerm_resource_group.changeme_simple_mssql_server_resource_group.name\n  location            = azurerm_resource_group.changeme_simple_mssql_server_resource_group.location\n  version = \"12.0\"\n  administrator_login          = \"changemeadmin\"\n  administrator_login_password = \"ch4ng3m3-A@Â£$%^&\"\n  public_network_access_enabled = false\n  minimum_tls_version           = \"1.2\"\n\n  extended_auditing_policy {\n    storage_endpoint                        = azurerm_storage_account.example.primary_blob_endpoint\n    storage_account_access_key              = azurerm_storage_account.example.primary_access_key\n    storage_account_access_key_is_secondary = false\n    retention_in_days                       = 90\n  }\n}\n\nresource \"azurerm_storage_account\" \"example\" {\n  name                     = \"changemestorageaccount\"\n  resource_group_name      = azurerm_resource_group.changeme_simple_mssql_server_resource_group.name\n  location                 = azurerm_resource_group.changeme_simple_mssql_server_resource_group.location\n  account_tier             = \"Standard\"\n  account_replication_type = \"LRS\"\n  account_kind             = \"StorageV2\"\n}",
  "fix_summary": "Enabled auditing with a retention period of 90 days, disabled public network access, and set the minimum TLS version to 1.2. Added a storage account for auditing and Vulnerability Assessment."
